// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function decimals() external view returns (uint8);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface ShibaMoon is IERC20 {}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);
    ShibaMoon target;
    IERC20 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ShibaMoon(payable(TARGET));
        vm.label(TARGET, "ShibaMoon Contract");
        vm.label(attacker, "Attacker");
        // Inject some BNB for gas
        deal(attacker, 1 ether);
        // Get token balance for testing
        token = IERC20(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Floating Pragma is a code quality issue, not runtime exploitable
        // This test demonstrates the contract functions normally despite the issue

        // Verify contract is deployed and accessible
        assertEq(target.name(), "ShibaMoon");
        assertEq(target.symbol(), "SHIBAMOON");
        assertEq(target.decimals(), 8);

        // Verify total supply exists
        uint256 totalSupply = target.totalSupply();
        assertGt(totalSupply, 0, "Total supply should be greater than 0");

        // Inject tokens to attacker for testing
        deal(TARGET, attacker, 1000000 * 10**8);

        // Verify attacker received tokens
        uint256 attackerBalance = token.balanceOf(attacker);
        assertGt(attackerBalance, 0, "Attacker should have tokens");

        // Demonstrate transfer works (no exploit possible from floating pragma)
        address recipient = address(0x1234567890123456789012345678901234567890);
        vm.prank(attacker);
        token.transfer(recipient, 1000 * 10**8);

        // Verify transfer succeeded
        assertEq(token.balanceOf(recipient), 1000 * 10**8, "Transfer should succeed");

        // The "vulnerability" is that pragma solidity ^0.6.12 allows multiple compiler versions
        // Fix: Change to pragma solidity 0.6.12; for reproducible builds
        // This cannot be exploited post-deployment as bytecode is immutable

        // Oracle check: pragma version should be ^0.6.12 (floating)
        // This is verified in source code, not runtime
        emit log("Floating Pragma: Code quality issue - requires source code fix");
        emit log("Cannot be exploited post-deployment");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

